export const STORAGE = Symbol('STORAGE');

/** Minimal object-storage contract, implemented for local disk (dev/test) and S3-compatible services. */
export interface StorageDriver {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
}

const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9/_\-.]*$/;

/** Keys are generated by the server; this guards against any traversal or odd characters. */
export function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..') || key.includes('//')) {
    throw new Error(`Unsafe storage key: ${key}`);
  }
}
